import { useContractorWorkers } from '@/hooks/contractor-management/use-contractor-workers';
import { useContractorCompanies } from '@/hooks/contractor-management/use-contractor-companies';
import { useActiveEvent } from '@/hooks/use-special-events';
import { canCloseOnSpot, type SeverityLevelV2 } from '@/lib/hsse-severity-levels';
import { NearestSiteResult } from '@/lib/geo-utils';
import { createQuickObservationSchema, FormValues, OBSERVATION_TYPES } from '../types';

export function useQuickObservationCardState() {
  const { t, i18n } = useTranslation();
  const direction = i18n.dir();
  const { profile } = useAuth();

  const schema = createQuickObservationSchema(t);

  const { isOnline } = useNetworkStatus();
  const { isCacheReady, getOfflineSites, getOfflineDepartments, getOfflineContractorCompanies, prefetchReportingData } = useOfflineReporting();
  const { addReport, pendingCount } = useOfflineReportQueue();

  const [isGettingLocation, setIsGettingLocation] = useState(false);
  const [gpsDetectedSite, setGpsDetectedSite] = useState<NearestSiteResult | null>(null);
  const [gpsError, setGpsError] = useState<'none' | 'not_supported' | 'permission_denied' | 'unavailable' | 'timeout' | 'no_nearby_site'>('none');
  const [photos, setPhotos] = useState<File[]>([]);
  const [closedOnSpotPhotos, setClosedOnSpotPhotos] = useState<File[]>([]);
  const [isUploading, setIsUploading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [submittedObservation, setSubmittedObservation] = useState<{ id: string; referenceId: string } | null>(null);
  const [hasSubmitted, setHasSubmitted] = useState(false);
  const [offlineSites, setOfflineSites] = useState<any[]>([]);
  const [offlineDepartments, setOfflineDepartments] = useState<any[]>([]);
  const [offlineContractorCompanies, setOfflineContractorCompanies] = useState<any[]>([]);

  const aiValidator = useObservationAIValidator();

  const { tags: availableObservationTags = [] } = useAITags('observation');
  const [selectedTags, setSelectedTags] = useState<string[]>([]);

  const createIncident = useCreateIncident();
  const { data: onlineSites = [] } = useTenantSites();
  const { data: tenantUsers = [] } = useTenantUsers();
  const { data: contractorWorkers = [] } = useContractorWorkers();
  const { data: onlineContractorCompanies = [] } = useContractorCompanies();
  const { data: activeEvent } = useActiveEvent();

  useEffect(() => {
    if (!isOnline && isCacheReady) {
      getOfflineSites().then(setOfflineSites);
      getOfflineDepartments().then(setOfflineDepartments);
      getOfflineContractorCompanies().then(setOfflineContractorCompanies);
    }
  }, [isOnline, isCacheReady, getOfflineSites, getOfflineDepartments, getOfflineContractorCompanies]);

  useEffect(() => {
    if (isOnline) prefetchReportingData();
  }, [isOnline, prefetchReportingData]);

  const sites = isOnline ? onlineSites : offlineSites;
  const contractorCompanies = isOnline ? onlineContractorCompanies : offlineContractorCompanies;

  const now = new Date();
  const currentDate = now.toISOString().split('T')[0];
  const currentTime = now.toTimeString().slice(0, 5);

  const form = useForm<FormValues>({
    resolver: zodResolver(schema),
    defaultValues: {
      description: '', subtype: '', severity_v2: 'level_2',
      observed_date: currentDate, observed_time: currentTime,
      site_id: profile?.assigned_site_id || '',
      latitude: undefined, longitude: undefined,
      closed_on_spot: false, recognition_type: undefined,
      recognized_user_id: undefined, recognized_department_id: undefined,
      recognized_contractor_worker_id: undefined, is_against_contractor: false,
      related_contractor_company_id: undefined,
    },
  });

  const closedOnSpot = form.watch('closed_on_spot');
  const selectedSeverity = form.watch('severity_v2');
  const selectedSubtype = form.watch('subtype');
  const recognitionType = form.watch('recognition_type');
  const isAgainstContractor = form.watch('is_against_contractor');
  const selectedSiteId = form.watch('site_id');

  const allowCloseOnSpot = canCloseOnSpot(selectedSeverity as SeverityLevelV2);

  const isPositiveObservation = useMemo(() => {
    const type = OBSERVATION_TYPES.find(t => t.value === selectedSubtype);
    return type?.isPositive ?? false;
  }, [selectedSubtype]);

  const selectedSite = useMemo(() => sites.find(s => s.id === selectedSiteId), [sites, selectedSiteId]);

  const observationBranchId = selectedSite?.branch_id || null;

  const { departments: siteDepartments = [], usingFallback: departmentsUsingFallback } = useDepartmentsBySite(selectedSiteId, observationBranchId || undefined);

  const departments = isOnline ? siteDepartments : offlineDepartments;

  const isCrossBranchReport = !!(observationBranchId && profile?.assigned_branch_id && observationBranchId !== profile.assigned_branch_id);

  const locationFilteredContractorCompanies = useMemo(() => {
    if (!observationBranchId) return contractorCompanies;
    return contractorCompanies.filter(company => company.assigned_branch_id === observationBranchId || !company.assigned_branch_id);
  }, [contractorCompanies, observationBranchId]);

  useEffect(() => {
    if (!isPositiveObservation) {
      form.setValue('recognition_type', undefined);
      form.setValue('recognized_user_id', undefined);
      form.setValue('recognized_department_id', undefined);
      form.setValue('recognized_contractor_worker_id', undefined);
    }
  }, [isPositiveObservation, form]);

  return {
    t, i18n, direction, profile, form,
    isOnline, pendingCount, isGettingLocation, setIsGettingLocation,
    gpsDetectedSite, setGpsDetectedSite, gpsError, setGpsError,
    photos, setPhotos, closedOnSpotPhotos, setClosedOnSpotPhotos,
    isUploading, setIsUploading, uploadProgress, setUploadProgress,
    submittedObservation, setSubmittedObservation, hasSubmitted, setHasSubmitted,
    aiValidator, availableObservationTags, selectedTags, setSelectedTags,
    createIncident, sites, tenantUsers, contractorWorkers, contractorCompanies,
    activeEvent, closedOnSpot, selectedSeverity, selectedSubtype, recognitionType,
    isAgainstContractor, selectedSiteId, allowCloseOnSpot, isPositiveObservation,
    selectedSite, observationBranchId, departments, isCrossBranchReport,
    locationFilteredContractorCompanies, addReport
  };
}

import { useState } from "react";
import { useTranslation } from "react-i18next";
import { format, subDays, subMonths, startOfMonth, endOfMonth } from "date-fns";
import { CalendarIcon } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Calendar } from "@/components/ui/calendar";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { cn } from "@/lib/utils";

interface DateRangeFilterProps {
  onDateRangeChange: (startDate: Date | undefined, endDate: Date | undefined) => void;
}

type PresetRange = 'last7days' | 'last30days' | 'last90days' | 'thisMonth' | 'lastMonth' | 'custom';

export function DateRangeFilter({ onDateRangeChange }: DateRangeFilterProps) {
  const { t } = useTranslation();
  const [preset, setPreset] = useState<PresetRange>('last30days');
  const [customStartDate, setCustomStartDate] = useState<Date>();
  const [customEndDate, setCustomEndDate] = useState<Date>();

  const handlePresetChange = (value: PresetRange) => {
    setPreset(value);
    const today = new Date();

    switch (value) {
      case 'last7days':
        onDateRangeChange(subDays(today, 7), today);
        break;
      case 'last30days':
        onDateRangeChange(subDays(today, 30), today);
        break;
      case 'last90days':
        onDateRangeChange(subDays(today, 90), today);
        break;
      case 'thisMonth':
        onDateRangeChange(startOfMonth(today), endOfMonth(today));
        break;
      case 'lastMonth':
        const lastMonth = subMonths(today, 1);
        onDateRangeChange(startOfMonth(lastMonth), endOfMonth(lastMonth));
        break;
      case 'custom':
        // Don't change dates, wait for user to pick
        break;
    }
  };

  const handleCustomDateChange = (start: Date | undefined, end: Date | undefined) => {
    setCustomStartDate(start);
    setCustomEndDate(end);
    if (start && end) {
      onDateRangeChange(start, end);
    }
  };

  return (
    <div className="flex items-center gap-2">
      <Select value={preset} onValueChange={(v) => handlePresetChange(v as PresetRange)}>
        <SelectTrigger className="w-[160px]">
          <SelectValue placeholder={t('hsseDashboard.dateRange')} />
        </SelectTrigger>
        <SelectContent>
          <SelectItem value="last7days">{t('hsseDashboard.dateRanges.last7Days', 'Last 7 Days')}</SelectItem>
          <SelectItem value="last30days">{t('hsseDashboard.dateRanges.last30Days', 'Last 30 Days')}</SelectItem>
          <SelectItem value="last90days">{t('hsseDashboard.dateRanges.last90Days', 'Last 90 Days')}</SelectItem>
          <SelectItem value="thisMonth">{t('hsseDashboard.dateRanges.thisMonth', 'This Month')}</SelectItem>
          <SelectItem value="lastMonth">{t('hsseDashboard.dateRanges.lastMonth', 'Last Month')}</SelectItem>
          <SelectItem value="custom">{t('hsseDashboard.dateRanges.custom', 'Custom')}</SelectItem>
        </SelectContent>
      </Select>

      {preset === 'custom' && (
        <div className="flex items-center gap-2">
          <Popover>
            <PopoverTrigger asChild>
              <Button
                variant="outline"
                size="sm"
                className={cn(
                  "w-[130px] justify-start text-start font-normal",
                  !customStartDate && "text-muted-foreground"
                )}
              >
                <CalendarIcon className="me-2 h-4 w-4" />
                {customStartDate ? format(customStartDate, "PP") : t('hsseDashboard.startDate', 'Start')}
              </Button>
            </PopoverTrigger>
            <PopoverContent className="w-auto p-0" align="start">
              <Calendar
                mode="single"
                selected={customStartDate}
                onSelect={(date) => handleCustomDateChange(date, customEndDate)}
                initialFocus
                className="pointer-events-auto"
              />
            </PopoverContent>
          </Popover>
          <span className="text-muted-foreground">ΓÇô</span>
          <Popover>
            <PopoverTrigger asChild>
              <Button
                variant="outline"
                size="sm"
                className={cn(
                  "w-[130px] justify-start text-start font-normal",
                  !customEndDate && "text-muted-foreground"
                )}
              >
                <CalendarIcon className="me-2 h-4 w-4" />
                {customEndDate ? format(customEndDate, "PP") : t('hsseDashboard.endDate', 'End')}
              </Button>
            </PopoverTrigger>
            <PopoverContent className="w-auto p-0" align="start">
              <Calendar
                mode="single"
                selected={customEndDate}
                onSelect={(date) => handleCustomDateChange(customStartDate, date)}
                initialFocus
                className="pointer-events-auto"
              />
            </PopoverContent>
          </Popover>
        </div>
      )}
    </div>
  );
}

import { useQuery } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Skeleton } from '@/components/ui/skeleton';
import { useTranslation } from 'react-i18next';
import { format } from 'date-fns';
import {
    Circle,
    CheckCircle2,
    Clock,
    ArrowDown,
    User,
    FileSearch,
    AlertTriangle
} from 'lucide-react';
import { Separator } from '@/components/ui/separator';

interface IncidentInvestigationTabProps {
    incidentId: string;
}

export function IncidentInvestigationTab({ incidentId }: IncidentInvestigationTabProps) {
    const { t } = useTranslation();

    const { data: investigation, isLoading } = useQuery<any>({
        queryKey: ['investigation-detail', incidentId],
        queryFn: async () => {
            const { data } = await supabase
                .from('investigations')
                .select(`
          *,
          investigator:profiles!investigator_id(full_name),
          team_leader:profiles!team_leader_id(full_name)
        `)
                .eq('incident_id', incidentId)
                .maybeSingle();
            return data as unknown;
        },
        enabled: !!incidentId
    });

    const { data: rca } = useQuery<any>({
        queryKey: ['rca-detail', incidentId],
        queryFn: async () => {
            const { data } = await supabase
                .from('rca_analyses' as unknown)
                .select('*')
                .eq('incident_id', incidentId)
                .maybeSingle();
            return data as unknown;
        },
        enabled: !!incidentId
    });

    if (isLoading) {
        return <Skeleton className="h-[400px] w-full" />;
    }

    return (
        <div className="space-y-6">
            <div className="grid gap-6 md:grid-cols-2">
                {/* Investigation Status Card */}
                <Card>
                    <CardHeader>
                        <CardTitle className="flex items-center gap-2">
                            <FileSearch className="h-5 w-5 text-primary" />
                            {t('investigation.details', 'Investigation Details')}
                        </CardTitle>
                    </CardHeader>
                    <CardContent className="space-y-4">
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <p className="text-sm font-medium text-muted-foreground">{t('investigation.investigator', 'Investigator')}</p>
                                <div className="flex items-center gap-2 mt-1">
                                    <User className="h-4 w-4 text-muted-foreground" />
                                    <span className="font-medium">{investigation?.investigator?.full_name || 'Unassigned'}</span>
                                </div>
                            </div>
                            <div>
                                <p className="text-sm font-medium text-muted-foreground">{t('investigation.startedAt', 'Started At')}</p>
                                <div className="flex items-center gap-2 mt-1">
                                    <Clock className="h-4 w-4 text-muted-foreground" />
                                    <span className="font-medium">
                                        {investigation?.started_at ? format(new Date(investigation.started_at), 'PP') : '-'}
                                    </span>
                                </div>
                            </div>
                        </div>

                        {investigation?.scope && (
                            <div className="mt-4">
                                <p className="text-sm font-medium text-muted-foreground mb-1">{t('investigation.scope', 'Scope')}</p>
                                <p className="text-sm bg-muted/50 p-3 rounded-md">{investigation.scope}</p>
                            </div>
                        )}
                    </CardContent>
                </Card>

                {/* RCA Summary Card */}
                <Card>
                    <CardHeader>
                        <CardTitle className="flex items-center gap-2">
                            <AlertTriangle className="h-5 w-5 text-amber-600" />
                            {t('investigation.rcaSummary', 'Root Cause Analysis')}
                        </CardTitle>
                    </CardHeader>
                    <CardContent className="space-y-4">
                        {rca ? (
                            <>
                                {rca.immediate_cause && (
                                    <div>
                                        <Badge variant="outline" className="mb-1 border-amber-500/50 text-amber-700 bg-amber-50">
                                            {t('rca.immediateCause', 'Immediate Cause')}
                                        </Badge>
                                        <p className="text-sm mt-1">{rca.immediate_cause}</p>
                                    </div>
                                )}
                                {rca.root_causes_summary && (
                                    <div>
                                        <Badge variant="outline" className="mb-1 border-destructive/50 text-destructive bg-destructive/5">
                                            {t('rca.rootCause', 'Root Cause')}
                                        </Badge>
                                        <p className="text-sm mt-1">{rca.root_causes_summary}</p>
                                    </div>
                                )}
                                {!rca.immediate_cause && !rca.root_causes_summary && (
                                    <p className="text-sm text-muted-foreground italic">
                                        {t('rca.noAnalysis', 'No detailed analysis recorded yet.')}
                                    </p>
                                )}
                            </>
                        ) : (
                            <div className="text-center py-6 text-muted-foreground">
                                {t('investigation.noRca', 'No RCA started.')}
                            </div>
                        )}
                    </CardContent>
                </Card>
            </div>

            {/* Timeline Placeholder - Enhancing this to be a real timeline visual */}
            <Card>
                <CardHeader>
                    <CardTitle>{t('investigation.timeline', 'Investigation Timeline')}</CardTitle>
                    <CardDescription>{t('investigation.timelineDesc', 'Key events and milestones')}</CardDescription>
                </CardHeader>
                <CardContent>
                    <div className="relative pl-6 border-l-2 border-muted space-y-8 my-4">

                        {/* Timeline Item: Incident Reported */}
                        <div className="relative">
                            <span className="absolute -left-[31px] top-1 h-6 w-6 rounded-full bg-primary flex items-center justify-center text-white ring-4 ring-background">
                                <AlertTriangle className="h-3 w-3" />
                            </span>
                            <div className="flex flex-col">
                                <span className="text-sm font-semibold">{t('status.incidentReported', 'Incident Reported')}</span>
                                <span className="text-xs text-muted-foreground">
                                    {/* We would put the date here from incident.created_at */}
                                    {t('common.initialReport', 'Initial Report')}
                                </span>
                            </div>
                        </div>

                        {/* Timeline Item: Investigation Started */}
                        {investigation?.started_at && (
                            <div className="relative">
                                <span className="absolute -left-[31px] top-1 h-6 w-6 rounded-full bg-blue-500 flex items-center justify-center text-white ring-4 ring-background">
                                    <FileSearch className="h-3 w-3" />
                                </span>
                                <div className="flex flex-col">
                                    <span className="text-sm font-semibold">{t('status.investigationStarted', 'Investigation Started')}</span>
                                    <span className="text-xs text-muted-foreground">
                                        {format(new Date(investigation.started_at), 'PP p')}
                                    </span>
                                </div>
                            </div>
                        )}

                        {/* Timeline Item: Completed */}
                        {investigation?.completed_at && (
                            <div className="relative">
                                <span className="absolute -left-[31px] top-1 h-6 w-6 rounded-full bg-green-500 flex items-center justify-center text-white ring-4 ring-background">
                                    <CheckCircle2 className="h-3 w-3" />
                                </span>
                                <div className="flex flex-col">
                                    <span className="text-sm font-semibold">{t('status.investigationCompleted', 'Investigation Completed')}</span>
                                    <span className="text-xs text-muted-foreground">
                                        {format(new Date(investigation.completed_at), 'PP p')}
                                    </span>
                                </div>
                            </div>
                        )}

                        {/* Future/Pending State */}
                        {!investigation?.completed_at && (
                            <div className="relative opacity-50">
                                <span className="absolute -left-[31px] top-1 h-6 w-6 rounded-full bg-muted border-2 border-muted-foreground/30 flex items-center justify-center ring-4 ring-background">
                                    <Circle className="h-3 w-3 text-muted-foreground" />
                                </span>
                                <div className="flex flex-col">
                                    <span className="text-sm font-semibold text-muted-foreground">{t('status.pendingCompletion', 'Pending Completion')}</span>
                                </div>
                            </div>
                        )}

                    </div>
                </CardContent>
            </Card>
        </div>
    );
}

