import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";
import { useAuth } from "@/contexts/AuthContext";

export type EscalationDecision = 'reject' | 'accept_observation' | 'upgrade_incident';

export interface EscalationReviewInput {
  incidentId: string;
  decision: EscalationDecision;
  notes?: string;
  investigatorId?: string; // Required for upgrade_incident
}

/**
 * Hook to check if user can review HSSE escalation for a specific observation
 */
export function useCanReviewHSSEEscalation(incidentId: string | null) {
  const { user } = useAuth();
  
  return useQuery({
    queryKey: ['can-review-hsse-escalation', user?.id, incidentId],
    queryFn: async () => {
      if (!user?.id || !incidentId) return false;
      
      // Check if user has HSSE role and incident is in pending_hsse_escalation_review status
      const { data: canPerform } = await supabase
        .rpc('can_perform_expert_screening', { _user_id: user.id });
      
      if (!canPerform) return false;
      
      // Check incident status
      const { data: incident } = await supabase
        .from('incidents')
        .select('status, event_type')
        .eq('id', incidentId)
        .single();
      
      // Use string comparison since new status may not be in types yet
      const status = incident?.status as string;
      return status === 'pending_hsse_escalation_review' && incident?.event_type === 'observation';
    },
    enabled: !!user?.id && !!incidentId,
  });
}

/**
 * Hook for HSSE Expert to review escalation requests from Dept Rep
 * 
 * Three decision options:
 * - reject: Escalation not justified, return to Dept Rep
 * - accept_observation: Confirm as observation, continue observation workflow
 * - upgrade_incident: Convert to incident with new INC reference
 */
export function useHSSEEscalationReview() {
  const queryClient = useQueryClient();
  const { toast } = useToast();
  const { user } = useAuth();
  
  return useMutation({
    mutationFn: async (input: EscalationReviewInput) => {
      const { incidentId, decision, notes, investigatorId } = input;
      
      // Get tenant_id
      const { data: profile } = await supabase
        .from('profiles')
        .select('tenant_id')
        .eq('id', user?.id)
        .single();
      
      if (!profile?.tenant_id) throw new Error('No tenant found');
      
      let newStatus: string;
      let newIncidentId: string | null = null;
      const updateData: Record<string, unknown> = {
        escalation_decision: decision,
        escalation_decision_by: user?.id,
        escalation_decision_at: new Date().toISOString(),
        escalation_decision_notes: notes,
      };
      
      switch (decision) {
        case 'reject':
          // Return to Dept Rep for action
          if (!notes || notes.length < 10) {
            throw new Error('Rejection reason is required (minimum 10 characters)');
          }
          newStatus = 'pending_dept_rep_approval';
          break;
          
        case 'accept_observation':
          // Continue as observation - go to HSSE validation or actions pending
          newStatus = 'pending_hsse_validation';
          break;
          
        case 'upgrade_incident':
          // Upgrade to incident using RPC function
          if (!investigatorId) {
            throw new Error('Investigator must be assigned when upgrading to incident');
          }
          
          const { data: upgradedIncidentId, error: upgradeError } = await supabase
            .rpc('upgrade_observation_to_incident', {
              p_observation_id: incidentId,
              p_user_id: user?.id,
              p_investigator_id: investigatorId,
              p_notes: notes || null,
            });
          
          if (upgradeError) throw upgradeError;
          
          newIncidentId = upgradedIncidentId as string;
          
          // The RPC already handles the status update, so we return early
          // Send notification
          try {
            await supabase.functions.invoke('send-workflow-notification', {
              body: { 
                incidentId, 
                action: 'escalation_upgraded',
                notes,
                newIncidentId,
                investigatorId,
              },
            });
          } catch (e) {
            console.error('Failed to send notification:', e);
          }
          
          return { incidentId, newStatus: 'upgraded_to_incident', newIncidentId };
          
        default:
          throw new Error('Invalid decision');
      }
      
      // For reject and accept_observation, update the incident
      updateData.status = newStatus;
      
      const { error } = await supabase
        .from('incidents')
        .update(updateData)
        .eq('id', incidentId);
      
      if (error) throw error;
      
      // Log audit entry
      await supabase.from('incident_audit_logs').insert({
        incident_id: incidentId,
        tenant_id: profile.tenant_id,
        actor_id: user?.id,
        action: `escalation_${decision}`,
        details: { decision, notes },
      });
      
      // Send notification
      try {
        await supabase.functions.invoke('send-workflow-notification', {
          body: { 
            incidentId, 
            action: `escalation_${decision}`,
            notes,
          },
        });
      } catch (e) {
        console.error('Failed to send notification:', e);
      }
      
      return { incidentId, newStatus, newIncidentId };
    },
    onSuccess: (result, variables) => {
      queryClient.invalidateQueries({ queryKey: ['incidents'] });
      queryClient.invalidateQueries({ queryKey: ['incident'] });
      queryClient.invalidateQueries({ queryKey: ['investigation'] });
      
      const messages: Record<EscalationDecision, { title: string; description: string }> = {
        reject: {
          title: "Escalation Rejected",
          description: "Observation returned to Department Representative",
        },
        accept_observation: {
          title: "Accepted as Observation",
          description: "Observation will continue through the observation workflow",
        },
        upgrade_incident: {
          title: "Upgraded to Incident",
          description: result.newIncidentId 
            ? "New incident created with investigation assigned"
            : "Observation has been upgraded to incident",
        },
      };
      
      const msg = messages[variables.decision];
      toast({
        title: msg.title,
        description: msg.description,
      });
    },
    onError: (error) => {
      toast({
        title: "Error",
        description: error.message,
        variant: "destructive",
      });
    },
  });
}

import { useState, useCallback, useRef } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { useToast } from '@/hooks/use-toast';
import { useTranslation } from 'react-i18next';
import i18n from '@/i18n';

export interface IncidentAnalysisResult {
  // Translation
  originalLanguage: string;
  originalText: string;
  translatedText: string;
  translationRequired: boolean;
  
  // Rewritten content
  rewrittenTitle: string;
  rewrittenDescription: string;
  
  // Quality Validation
  clarityScore: number;
  
  // Classification
  eventType: 'observation' | 'incident';
  incidentType: string | null;
  incidentTypeConfidence: number;
  subtype: string;
  subtypeConfidence: number;
  severity: string;
  severityConfidence: number;
  
  // Injury/Damage
  hasInjury: boolean;
  injuryCount?: number;
  injuryType?: string;
  injuryDescription?: string;
  hasDamage: boolean;
  damageDescription?: string;
  estimatedCost?: number;
  
  // Key Risks & Actions
  keyRisks: string[];
  immediateActions: string[];
  
  // Tags
  suggestedTags: string[];
  
  // Confidence
  confidence: number;
  reasoning?: string;
}

export type IncidentValidationState = 
  | 'idle'
  | 'analyzing'
  | 'awaiting_translation_confirm'
  | 'analysis_ready'
  | 'validated';

export interface IncidentContext {
  location?: string;
  assetId?: string;
}

export interface UseIncidentAIValidatorReturn {
  // State
  validationState: IncidentValidationState;
  analysisResult: IncidentAnalysisResult | null;
  error: string | null;
  processingTime: number;
  
  // Actions
  analyzeIncident: (title: string, description: string, context?: IncidentContext) => Promise<void>;
  confirmTranslation: () => void;
  confirmAnalysis: () => void;
  reset: () => void;
  
  // Helpers
  getRewrittenContent: () => { title: string; description: string } | null;
  
  // Validation checks
  isAnalyzing: boolean;
}

export function useIncidentAIValidator(): UseIncidentAIValidatorReturn {
  const { t } = useTranslation();
  const { toast } = useToast();
  
  const [validationState, setValidationState] = useState<IncidentValidationState>('idle');
  const [analysisResult, setAnalysisResult] = useState<IncidentAnalysisResult | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [processingTime, setProcessingTime] = useState(0);
  
  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const startTimeRef = useRef<number>(0);

  const startTimer = useCallback(() => {
    startTimeRef.current = Date.now();
    timerRef.current = setInterval(() => {
      setProcessingTime(Math.floor((Date.now() - startTimeRef.current) / 1000));
    }, 100);
  }, []);

  const stopTimer = useCallback(() => {
    if (timerRef.current) {
      clearInterval(timerRef.current);
      timerRef.current = null;
    }
    setProcessingTime(Math.floor((Date.now() - startTimeRef.current) / 1000));
  }, []);

  const analyzeIncident = useCallback(async (title: string, description: string, context?: IncidentContext) => {
    // Reset state
    setError(null);
    setAnalysisResult(null);
    setValidationState('analyzing');
    startTimer();

    try {
      const { data, error: fnError } = await supabase.functions.invoke('analyze-incident', {
        body: { 
          description,
          title,
          responseLanguage: i18n.language,
          context: context || {} // Pass context to Edge Function
        }
      });

      stopTimer();

      if (fnError) {
        throw new Error(fnError.message || 'AI analysis failed');
      }

      if (data?.error) {
        // Handle specific error types
        if (data.error.includes('Rate limit')) {
          toast({
            title: t('common.error'),
            description: t('incidents.ai.rateLimitError', 'Rate limit exceeded. Please wait and try again.'),
            variant: 'destructive',
          });
        } else if (data.error.includes('credits')) {
          toast({
            title: t('common.error'),
            description: t('incidents.ai.creditsError', 'AI credits exhausted. Please contact administrator.'),
            variant: 'destructive',
          });
        }
        throw new Error(data.error);
      }

      // Detect if translation was required (non-English input)
      const isNonEnglish = /[\u0600-\u06FF\u0900-\u097F\u0C00-\u0C7F]/.test(description);
      
      const result: IncidentAnalysisResult = {
        // Translation
        originalLanguage: isNonEnglish ? 'Non-English' : 'English',
        originalText: description,
        translatedText: data.rewrittenDescription || description,
        translationRequired: isNonEnglish,
        
        // Rewritten content
        rewrittenTitle: data.rewrittenTitle || title,
        rewrittenDescription: data.rewrittenDescription || description,
        
        // Quality
        clarityScore: data.clarityScore || 75,
        
        // Classification
        eventType: data.eventType || 'incident',
        incidentType: data.incidentType || null,
        incidentTypeConfidence: (data.confidence || 0.8) * 100,
        subtype: data.subtype || '',
        subtypeConfidence: (data.confidence || 0.8) * 100,
        severity: data.severity || 'medium',
        severityConfidence: (data.confidence || 0.8) * 100 - 5,
        
        // Injury/Damage
        hasInjury: data.hasInjury || false,
        injuryCount: data.injuryCount,
        injuryType: data.injuryType,
        injuryDescription: data.injuryDescription,
        hasDamage: data.hasDamage || false,
        damageDescription: data.damageDescription,
        estimatedCost: data.estimatedCost,
        
        // Key Risks & Actions
        keyRisks: data.keyRisks || [],
        immediateActions: data.immediateActions || [],
        
        // Tags
        suggestedTags: data.suggestedTags || [],
        
        // Confidence
        confidence: data.confidence || 0.8,
        reasoning: data.reasoning,
      };
      
      setAnalysisResult(result);

      // Determine next state
      if (isNonEnglish) {
        setValidationState('awaiting_translation_confirm');
      } else {
        setValidationState('analysis_ready');
      }

    } catch (err) {
      stopTimer();
      const errorMessage = err instanceof Error ? err.message : 'Unknown error';
      setError(errorMessage);
      setValidationState('idle');
      
      toast({
        title: t('common.error'),
        description: errorMessage,
        variant: 'destructive',
      });
    }
  }, [t, toast, startTimer, stopTimer]);

  const confirmTranslation = useCallback(() => {
    setValidationState('analysis_ready');
  }, []);

  const confirmAnalysis = useCallback(() => {
    setValidationState('validated');
  }, []);

  const getRewrittenContent = useCallback(() => {
    if (!analysisResult) return null;
    return {
      title: analysisResult.rewrittenTitle,
      description: analysisResult.rewrittenDescription,
    };
  }, [analysisResult]);

  const reset = useCallback(() => {
    setValidationState('idle');
    setAnalysisResult(null);
    setError(null);
    setProcessingTime(0);
    if (timerRef.current) {
      clearInterval(timerRef.current);
      timerRef.current = null;
    }
  }, []);

  return {
    validationState,
    analysisResult,
    error,
    processingTime,
    analyzeIncident,
    confirmTranslation,
    confirmAnalysis,
    reset,
    getRewrittenContent,
    isAnalyzing: validationState === 'analyzing',
  };
}

import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import { useToast } from '@/hooks/use-toast';
import { useAuth } from '@/contexts/AuthContext';

export type ConfidentialityLevel = 'public' | 'restricted' | 'confidential';

export interface ConfidentialitySettings {
  level: ConfidentialityLevel;
  expiry: string | null;
  autoDeclassifyTo: 'public' | 'restricted' | null;
  expiryReason: string | null;
  setBy: string | null;
  setAt: string | null;
}

export interface AccessListUser {
  id: string;
  user_id: string;
  full_name: string;
  email?: string;
  granted_by_name: string;
  granted_at: string;
  reason?: string;
}

export interface ConfidentialityAuditEntry {
  id: string;
  action: string;
  old_level: string | null;
  new_level: string | null;
  actor_name: string;
  affected_user_name?: string;
  reason?: string;
  created_at: string;
}

// Check if user can set confidentiality level
export function useCanSetConfidentiality(incidentId: string) {
  const { user } = useAuth();
  
  return useQuery({
    queryKey: ['can-set-confidentiality', incidentId, user?.id],
    queryFn: async () => {
      if (!user?.id) return false;
      
      const { data, error } = await supabase.rpc('can_set_confidentiality', {
        _user_id: user.id,
        _incident_id: incidentId
      });
      
      if (error) {
        console.error('Error checking confidentiality permission:', error);
        return false;
      }
      
      return data as boolean;
    },
    enabled: !!incidentId && !!user?.id
  });
}

// Check if user can manage access list (HSSE Manager only)
export function useCanManageAccessList() {
  const { user } = useAuth();
  
  return useQuery({
    queryKey: ['can-manage-access-list', user?.id],
    queryFn: async () => {
      if (!user?.id) return false;
      
      const { data, error } = await supabase.rpc('can_manage_access_list', {
        _user_id: user.id
      });
      
      if (error) {
        console.error('Error checking access list permission:', error);
        return false;
      }
      
      return data as boolean;
    },
    enabled: !!user?.id
  });
}

// Check if user has confidentiality access to incident
export function useHasConfidentialityAccess(incidentId: string) {
  const { user } = useAuth();
  
  return useQuery({
    queryKey: ['has-confidentiality-access', incidentId, user?.id],
    queryFn: async () => {
      if (!user?.id) return false;
      
      const { data, error } = await supabase.rpc('has_confidentiality_access', {
        _incident_id: incidentId,
        _user_id: user.id
      });
      
      if (error) {
        console.error('Error checking confidentiality access:', error);
        return false;
      }
      
      return data as boolean;
    },
    enabled: !!incidentId && !!user?.id
  });
}

// Get incident confidentiality settings
export function useIncidentConfidentiality(incidentId: string) {
  return useQuery({
    queryKey: ['incident-confidentiality', incidentId],
    queryFn: async () => {
      const { data, error } = await supabase
        .from('incidents')
        .select('confidentiality_level, confidentiality_expiry, auto_declassify_to, confidentiality_expiry_reason, confidentiality_set_by, confidentiality_set_at')
        .eq('id', incidentId)
        .single();
      
      if (error) throw error;
      
      return {
        level: (data.confidentiality_level || 'public') as ConfidentialityLevel,
        expiry: data.confidentiality_expiry,
        autoDeclassifyTo: data.auto_declassify_to as 'public' | 'restricted' | null,
        expiryReason: data.confidentiality_expiry_reason,
        setBy: data.confidentiality_set_by,
        setAt: data.confidentiality_set_at
      } as ConfidentialitySettings;
    },
    enabled: !!incidentId
  });
}

// Get access list for confidential incidents
export function useIncidentAccessList(incidentId: string) {
  return useQuery({
    queryKey: ['incident-access-list', incidentId],
    queryFn: async () => {
      const { data, error } = await supabase
        .from('incident_access_list')
        .select(`
          id,
          user_id,
          user:user_id(full_name, email),
          granted_by_user:granted_by(full_name),
          granted_at,
          reason
        `)
        .eq('incident_id', incidentId)
        .is('revoked_at', null)
        .is('deleted_at', null)
        .order('granted_at', { ascending: false });
      
      if (error) throw error;
      
      return (data || []).map((item: Record<string, unknown>) => ({
        id: item.id as string,
        user_id: item.user_id as string,
        full_name: (item.user as { full_name: string } | null)?.full_name || 'Unknown',
        email: (item.user as { email: string } | null)?.email,
        granted_by_name: (item.granted_by_user as { full_name: string } | null)?.full_name || 'Unknown',
        granted_at: item.granted_at as string,
        reason: item.reason as string | undefined
      })) as AccessListUser[];
    },
    enabled: !!incidentId
  });
}

// Get confidentiality audit history
export function useConfidentialityAudit(incidentId: string) {
  return useQuery({
    queryKey: ['confidentiality-audit', incidentId],
    queryFn: async () => {
      const { data, error } = await supabase
        .from('incident_confidentiality_audit')
        .select(`
          id,
          action,
          old_level,
          new_level,
          actor:actor_id(full_name),
          affected_user:affected_user_id(full_name),
          reason,
          created_at
        `)
        .eq('incident_id', incidentId)
        .order('created_at', { ascending: false });
      
      if (error) throw error;
      
      return (data || []).map((item: Record<string, unknown>) => ({
        id: item.id as string,
        action: item.action as string,
        old_level: item.old_level as string | null,
        new_level: item.new_level as string | null,
        actor_name: (item.actor as { full_name: string } | null)?.full_name || 'System',
        affected_user_name: (item.affected_user as { full_name: string } | null)?.full_name,
        reason: item.reason as string | undefined,
        created_at: item.created_at as string
      })) as ConfidentialityAuditEntry[];
    },
    enabled: !!incidentId
  });
}

// Update confidentiality settings
export function useUpdateConfidentiality() {
  const queryClient = useQueryClient();
  const { toast } = useToast();
  const { user } = useAuth();
  
  return useMutation({
    mutationFn: async ({ 
      incidentId, 
      level, 
      expiry, 
      autoDeclassifyTo, 
      expiryReason 
    }: {
      incidentId: string;
      level: ConfidentialityLevel;
      expiry?: string | null;
      autoDeclassifyTo?: 'public' | 'restricted' | null;
      expiryReason?: string | null;
    }) => {
      const { error } = await supabase
        .from('incidents')
        .update({
          confidentiality_level: level,
          confidentiality_expiry: level !== 'public' ? expiry : null,
          auto_declassify_to: level !== 'public' ? autoDeclassifyTo : null,
          confidentiality_expiry_reason: level !== 'public' ? expiryReason : null,
          confidentiality_set_by: user?.id,
          confidentiality_set_at: new Date().toISOString()
        })
        .eq('id', incidentId);
      
      if (error) throw error;
    },
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({ queryKey: ['incident-confidentiality', variables.incidentId] });
      queryClient.invalidateQueries({ queryKey: ['confidentiality-audit', variables.incidentId] });
      queryClient.invalidateQueries({ queryKey: ['incident', variables.incidentId] });
      toast({
        title: 'Confidentiality Updated',
        description: `Incident confidentiality level set to ${variables.level}`
      });
    },
    onError: (error) => {
      toast({
        title: 'Update Failed',
        description: error instanceof Error ? error.message : 'Failed to update confidentiality',
        variant: 'destructive'
      });
    }
  });
}

// Grant access to user (for confidential level)
export function useGrantAccess() {
  const queryClient = useQueryClient();
  const { toast } = useToast();
  const { user, profile } = useAuth();
  const tenantId = profile?.tenant_id;
  
  return useMutation({
    mutationFn: async ({ incidentId, userId, reason }: { 
      incidentId: string; 
      userId: string; 
      reason?: string;
    }) => {
      // Insert or update (upsert would need unique constraint handling)
      const { error } = await supabase
        .from('incident_access_list')
        .upsert({
          tenant_id: tenantId!,
          incident_id: incidentId,
          user_id: userId,
          granted_by: user?.id!,
          granted_at: new Date().toISOString(),
          reason,
          revoked_at: null,
          revoked_by: null
        }, {
          onConflict: 'incident_id,user_id'
        });
      
      if (error) throw error;
      
      // Log to audit
      await supabase.from('incident_confidentiality_audit').insert({
        tenant_id: tenantId!,
        incident_id: incidentId,
        actor_id: user?.id!,
        action: 'access_granted',
        affected_user_id: userId,
        reason
      });
    },
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({ queryKey: ['incident-access-list', variables.incidentId] });
      queryClient.invalidateQueries({ queryKey: ['confidentiality-audit', variables.incidentId] });
      toast({
        title: 'Access Granted',
        description: 'User has been granted access to this incident'
      });
    },
    onError: (error) => {
      toast({
        title: 'Grant Failed',
        description: error instanceof Error ? error.message : 'Failed to grant access',
        variant: 'destructive'
      });
    }
  });
}

// Revoke access from user
export function useRevokeAccess() {
  const queryClient = useQueryClient();
  const { toast } = useToast();
  const { user, profile } = useAuth();
  const tenantId = profile?.tenant_id;
  
  return useMutation({
    mutationFn: async ({ accessId, incidentId, userId, reason }: { 
      accessId: string;
      incidentId: string; 
      userId: string;
      reason?: string;
    }) => {
      const { error } = await supabase
        .from('incident_access_list')
        .update({
          revoked_at: new Date().toISOString(),
          revoked_by: user?.id
        })
        .eq('id', accessId);
      
      if (error) throw error;
      
      // Log to audit
      await supabase.from('incident_confidentiality_audit').insert({
        tenant_id: tenantId!,
        incident_id: incidentId,
        actor_id: user?.id!,
        action: 'access_revoked',
        affected_user_id: userId,
        reason
      });
    },
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({ queryKey: ['incident-access-list', variables.incidentId] });
      queryClient.invalidateQueries({ queryKey: ['confidentiality-audit', variables.incidentId] });
      toast({
        title: 'Access Revoked',
        description: 'User access has been revoked'
      });
    },
    onError: (error) => {
      toast({
        title: 'Revoke Failed',
        description: error instanceof Error ? error.message : 'Failed to revoke access',
        variant: 'destructive'
      });
    }
  });
}

