          </div>

          {/* Link Button */}
          <Button onClick={handleLink} disabled={linkMutation.isPending} className="w-full">
            <Link2 className="h-4 w-4 me-2" />
            {linkMutation.isPending ? t('common.saving') : t('assetManagement.linkAsset')}
          </Button>
        </>
      )}
    </div>
  );
